using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class PlantHillTrees {
 const string A="Assets/NewMap/FiveHangars/HillTrees";
 struct Tree {public Vector3 p;public float scale,yaw;public int type;public bool distant;}
 static Vector3[] backdropVertices;static int[] backdropTriangles;
 static bool BackdropHeight(Vector3 p,out float height){height=0;for(int k=0;k<backdropTriangles.Length;k+=3){var a=backdropVertices[backdropTriangles[k]];var b=backdropVertices[backdropTriangles[k+1]];var c=backdropVertices[backdropTriangles[k+2]];float denominator=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(denominator)<.00001f)continue;float u=((b.z-c.z)*(p.x-c.x)+(c.x-b.x)*(p.z-c.z))/denominator;float v=((c.z-a.z)*(p.x-c.x)+(a.x-c.x)*(p.z-c.z))/denominator;float w=1-u-v;if(u<-.0001f||v<-.0001f||w<-.0001f)continue;height=u*a.y+v*b.y+w*c.y;return true;}return false;}
 public static string Main(){
  if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var root=GameObject.Find("New_Map").transform;var parent=root.Find("12_Farmyards_and_boundaries");if(parent.Find("Low poly hill groves"))throw new Exception("Hill groves already planted");var terrain=root.GetComponentInChildren<Terrain>();
  Directory.CreateDirectory("Temp/FiveHangars");EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/FiveHangars/Gameplay.before-hill-trees.unity",true);Directory.CreateDirectory(A);AssetDatabase.Refresh();
  var sources=root.Find("05_Landscape").GetComponentsInChildren<LODGroup>().Where(l=>l.name.StartsWith("TFP_Beech_Tree_")).GroupBy(l=>l.name).Select(g=>g.First()).Take(3).ToArray();if(sources.Length<2)throw new Exception("Need at least two existing tree variants");
  var backdrop=parent.Find("Distant rolling hills - backdrop");var bm=backdrop.GetComponent<MeshFilter>().sharedMesh;backdropVertices=bm.vertices.Select(v=>backdrop.TransformPoint(v)).ToArray();backdropTriangles=bm.triangles;
  var rng=new System.Random(2601026);Func<float,float,float> random=(a,b)=>Mathf.Lerp(a,b,(float)rng.NextDouble());var trees=new List<Tree>();
  // Irregular clusters on the perimeter slopes, behind the farm fences.
  for(float z=-66;z<310;z+=8.5f)for(float x=-188;x<188;x+=8.5f){var p=new Vector3(x+random(-3,3),0,z+random(-3,3));float edge=Mathf.Min(Mathf.Min(p.x+192,192-p.x),Mathf.Min(p.z+70,314-p.z));if(edge<3||edge>26)continue;float density=Mathf.PerlinNoise(p.x*.026f+70,p.z*.026f+29);if(rng.NextDouble()>.36f+density*.52f)continue;p.y=terrain.SampleHeight(p)+terrain.transform.position.y-.12f;trees.Add(new Tree{p=p,scale=random(.7f,1.25f),yaw=random(0,360),type=rng.Next(sources.Length)});}
  // Ground far silhouettes on the actual triangulated backdrop, not a flat ring.
  for(float z=-178;z<422;z+=13)for(float x=-300;x<300;x+=13){var p=new Vector3(x+random(-4.5f,4.5f),0,z+random(-4.5f,4.5f));if(p.x>-191&&p.x<191&&p.z>-69&&p.z<313)continue;float height;if(!BackdropHeight(p,out height))continue;if(rng.NextDouble()>.3f+Mathf.PerlinNoise(p.x*.019f+14,p.z*.019f+61)*.48f)continue;p.y=height-.12f;trees.Add(new Tree{p=p,scale=random(.85f,1.5f),yaw=random(0,360),type=rng.Next(sources.Length),distant=true});}
  var group=new GameObject("Low poly hill groves").transform;group.SetParent(parent,false);Undo.RegisterCreatedObjectUndo(group.gameObject,"Plant low poly hill groves");int serial=0,renderers=0;
  AssetDatabase.StartAssetEditing();try{
   foreach(var cell in trees.GroupBy(t=>(t.distant?"Outer ":"Slope ")+Mathf.FloorToInt(t.p.x/42)+"_"+Mathf.FloorToInt(t.p.z/42))){var g=new GameObject(cell.Key).transform;g.SetParent(group,false);g.position=new Vector3(cell.Average(t=>t.p.x),cell.Average(t=>t.p.y),cell.Average(t=>t.p.z));var lod=g.gameObject.AddComponent<LODGroup>();var levels=new LOD[3];
    for(int level=0;level<3;level++){var byMaterial=new Dictionary<Material,List<CombineInstance>>();foreach(var tree in cell){var source=sources[tree.type];var sl=source.GetLODs();var levelRenderers=sl[Mathf.Min(level,sl.Length-1)].renderers;foreach(var r in levelRenderers.OfType<MeshRenderer>()){var mesh=r.GetComponent<MeshFilter>().sharedMesh;var matrix=g.worldToLocalMatrix*Matrix4x4.TRS(tree.p,Quaternion.Euler(0,tree.yaw,0),Vector3.one*tree.scale)*source.transform.worldToLocalMatrix*r.transform.localToWorldMatrix;for(int sub=0;sub<mesh.subMeshCount;sub++){var mat=r.sharedMaterials[Mathf.Min(sub,r.sharedMaterials.Length-1)];if(!byMaterial.ContainsKey(mat))byMaterial.Add(mat,new List<CombineInstance>());byMaterial[mat].Add(new CombineInstance{mesh=mesh,subMeshIndex=sub,transform=matrix});}}}
     var parts=new List<Mesh>();foreach(var entries in byMaterial){var m=new Mesh{indexFormat=IndexFormat.UInt32};m.CombineMeshes(entries.Value.ToArray(),true,true);parts.Add(m);}var combined=new Mesh{name=cell.Key+" LOD "+level,indexFormat=IndexFormat.UInt32};combined.CombineMeshes(parts.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,false);combined.RecalculateBounds();AssetDatabase.CreateAsset(combined,A+"/Hill grove "+(++serial)+".asset");foreach(var m in parts)Object.DestroyImmediate(m);
     var child=new GameObject("Combined tree LOD "+level);child.transform.SetParent(g,false);child.AddComponent<MeshFilter>().sharedMesh=combined;var renderer=child.AddComponent<MeshRenderer>();renderer.sharedMaterials=byMaterial.Keys.ToArray();renderer.shadowCastingMode=cell.First().distant?ShadowCastingMode.Off:ShadowCastingMode.On;levels[level]=new LOD(level==0?.45f:level==1?.18f:.012f,new Renderer[]{renderer});renderers++;
    }lod.SetLODs(levels);lod.RecalculateBounds();
   }
  }finally{AssetDatabase.StopAssetEditing();}
  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);string report="Planted "+trees.Count+" low-poly trees: "+trees.Count(t=>!t.distant)+" on perimeter slopes and "+trees.Count(t=>t.distant)+" on distant hills. "+sources.Length+" existing beech variants, irregular groves with varied scale/rotation. Combined into "+group.childCount+" spatial cells / "+renderers+" LOD renderers; no per-tree hierarchy or new colliders. Trees grounded on terrain/backdrop triangles. Gameplay area, roads, doors and shop unchanged.";Directory.CreateDirectory("output/NewMap/FiveHangars");File.WriteAllText("output/NewMap/FiveHangars/hill-trees.txt",report);return report;
 }
}
